using Common.Dtos;
using Common.Exceptions;
using Common.Utils;
using EduCore_BusinessLayer;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.AspNetCore.RateLimiting;

namespace EduCoreAPI.Controllers
{
    [Route("api/certificates")]
    [ApiController]
    public class CertificatesController : ControllerBase
    {
        // Certificate codes are always GUID-shaped (generated by
        // SP_IssueCertificate). Rejecting anything else up front keeps the
        // download path free of user-controlled path segments.
        private static bool IsValidCode(string code)
            => Guid.TryParseExact(code, "N", out _);

        // =========================
        // GET: Verify a certificate (public)
        // =========================
        [AllowAnonymous]
        [HttpGet("{code}")]
        public async Task<ActionResult> Verify([FromRoute] string code)
        {
            if (!IsValidCode(code))
                throw new NotFoundException("Certificate not found");

            DtoCertificate? certificate =
                await clsProgress.GetCertificateByCode(code);

            if (certificate is null)
                throw new NotFoundException("Certificate not found");

            // Public verification exposes only the display metadata —
            // no email, no ids beyond the code, no file paths.
            return Ok(new
            {
                isValid = true,
                certificate.CertificateCode,
                certificate.StudentName,
                certificate.CourseTitle,
                certificate.IssuedAt
            });
        }

        // =========================
        // GET: Download certificate PDF (owner or admin)
        // =========================
        [Authorize]
        [HttpGet("{code}/download")]
        [EnableRateLimiting("AuthLimiter")]
        public async Task<ActionResult> Download(
            [FromRoute] string code,
            [FromServices] IAuthorizationService authorizationService)
        {
            if (!IsValidCode(code))
                throw new NotFoundException("Certificate not found");

            DtoCertificate? certificate =
                await clsProgress.GetCertificateByCode(code);

            if (certificate is null)
                throw new NotFoundException("Certificate not found");

            var authResult = await authorizationService.AuthorizeAsync(
                User,
                certificate.UserId,
                "UserOwnerOrAdmin");

            if (!authResult.Succeeded)
                return Forbid(); // 403

            string pdfPath = Path.Combine(
                clsProgress.CertificatesDirectory,
                $"{certificate.CertificateCode}.pdf");

            if (!System.IO.File.Exists(pdfPath))
                throw new NotFoundException(
                    "Certificate file is not available. Please re-issue the certificate.");

            return PhysicalFile(
                pdfPath,
                "application/pdf",
                $"EduCore-Certificate-{certificate.CertificateCode}.pdf");
        }
    }
}
